// Lee ventas/seguimiento.md y extrae la tabla '## Tabla de seguimiento'.
// Devuelve UN item: { hoy, total, toques[] } con los toques cuyo 'Próximo toque' vence hoy o ya venció.
const md = String($input.first().json.data ?? $input.first().json.body ?? '');
const ahora = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Madrid' }));
const hoy = new Date(ahora.getFullYear(), ahora.getMonth(), ahora.getDate());

const MESES = { ene: 0, feb: 1, mar: 2, abr: 3, may: 4, jun: 5, jul: 6, ago: 7, sept: 8, sep: 8, oct: 9, nov: 10, dic: 11 };
const limpiar = (s) => (s || '').replace(/\*\*/g, '').trim();

function parseFecha(txt) {
  const m = limpiar(txt).toLowerCase().match(/(\d{1,2})[-\/\s]*(sept|ene|feb|mar|abr|may|jun|jul|ago|sep|oct|nov|dic)/);
  if (!m) return null;
  const dia = parseInt(m[1], 10);
  let f = new Date(hoy.getFullYear(), MESES[m[2]], dia);
  // La tabla no lleva año: si queda a más de medio año de distancia, corrige de año.
  const medioAnio = 182 * 86400000;
  if (f.getTime() - hoy.getTime() > medioAnio) f = new Date(hoy.getFullYear() - 1, MESES[m[2]], dia);
  else if (hoy.getTime() - f.getTime() > medioAnio) f = new Date(hoy.getFullYear() + 1, MESES[m[2]], dia);
  return f;
}

const seccion = md.split(/^##\s+Tabla de seguimiento\s*$/m)[1];
if (!seccion) throw new Error("No encuentro la sección '## Tabla de seguimiento' en seguimiento.md — ¿ha cambiado el formato del tracker?");
const cuerpo = seccion.split(/^##\s+/m)[0];

const filas = cuerpo.split('\n').filter((l) => l.trim().startsWith('|'));
const toques = [];
for (const linea of filas.slice(2)) { // salta cabecera y separador
  const c = linea.split('|').slice(1, -1).map(limpiar);
  if (c.length < 8 || !c[0] || /^-+$/.test(c[0])) continue;
  const proximo = parseFecha(c[5]);
  if (!proximo) continue;
  const diffDias = Math.round((proximo.getTime() - hoy.getTime()) / 86400000);
  if (diffDias > 0) continue; // solo lo que vence hoy o ya venció
  const toqueM = c[4].match(/d[ií]a\s*(\d+)/i);
  toques.push({
    cuenta: c[0],
    contacto: c[1],
    canal: c[2],
    ultimoContacto: c[3],
    toque: c[4],
    dia: toqueM ? parseInt(toqueM[1], 10) : null,
    proximoToque: proximo.toISOString().slice(0, 10),
    vencidoDias: -diffDias,
    estado: c[6],
    material: c[7],
  });
}

return [{ json: { hoy: hoy.toISOString().slice(0, 10), total: toques.length, toques } }];

// Convierte cada toque en un texto listo para revisar. NADA se envía a clientes desde aquí.
const { toques, hoy } = $input.first().json;

function plantilla(t) {
  const nombre = ((t.contacto || '').split('/')[0].trim().split(' ')[0]) || '';
  const saludo = nombre ? `Hola ${nombre},` : 'Hola,';
  if (/emana/i.test(t.cuenta)) {
    return `⚠️ CUENTA RELACIÓN, NO VENTA (regla del pipeline: cero pitch y cero enlace de calendario hasta que ella abra la puerta comercial).\n\nNo usar plantilla comercial. Confirmar con el cerebro si la respuesta escrita por el SDR (rama outbound, captacion/despliegue-cola-25ago.md) se aprobó y envió antes de tocar nada.`;
  }
  if (t.dia === 3) return `${saludo}\n\nte escribí hace unos días y no quiero que se pierda en la bandeja. Si te encaja, te mando en dos líneas cómo lo enfocaría para ${t.cuenta} — sin reunión de por medio. ¿Te lo paso?`;
  if (t.dia === 7) return `${saludo}\n\nuna sola pregunta rápida para no robarte tiempo: ¿esto es algo que tenéis sobre la mesa este trimestre en ${t.cuenta}, o lo aparco? Con un sí o un no me vale.`;
  if (t.dia === 14) return `${saludo}\n\ncierro el hilo por mi parte para no insistir. Si más adelante vuelve a la mesa, retomamos donde lo dejamos. Un abrazo y buen cierre de trimestre.`;
  return `${saludo}\n\n(retomo el hilo — toque sin día de cadencia definido en el tracker: redactar a mano según contexto)`;
}

if (!toques || toques.length === 0) {
  return [{ json: { sinToques: true, hoy, esEmail: false } }];
}

return toques.map((t) => {
  const esEmail = /mail/i.test(t.canal);
  const cabecera =
    `── CONTEXTO (borrar antes de enviar) ──\n` +
    `Cuenta: ${t.cuenta} · Contacto: ${t.contacto} · Canal: ${t.canal}\n` +
    `Toque: ${t.toque || 'seguimiento'} · Vencía: ${t.proximoToque} (${t.vencidoDias} día(s) de retraso)\n` +
    `Último contacto: ${t.ultimoContacto}\n` +
    `Estado: ${t.estado}\n` +
    `Material del agente de ventas: ${t.material}\n` +
    `───────────────────────────\n\n`;
  return {
    json: {
      ...t,
      hoy,
      esEmail,
      asunto: `[BORRADOR ${t.toque || 'seguimiento'}] ${t.cuenta} — revisar y enviar a mano`,
      cuerpo: cabecera + plantilla(t),
      textoToque: plantilla(t),
    },
  };
});

// Un solo email-resumen interno para Maikel con la lista de toques del día.
const items = $input.all().map((i) => i.json);
const hoy = items[0].hoy || new Date().toISOString().slice(0, 10);

let cuerpo;
let titulo;
if (items[0].sinToques) {
  titulo = 'ninguno';
  cuerpo = `Sin toques de seguimiento que venzan hoy (${hoy}). ✅\n\nFuente: ventas/seguimiento.md`;
} else {
  titulo = String(items.length);
  const bloques = items.map((t) => {
    let b = `• ${t.cuenta} — ${t.toque || 'seguimiento'} (vencía ${t.proximoToque}, ${t.vencidoDias} día(s) de retraso) · canal: ${t.canal}\n  Estado: ${t.estado}\n`;
    if (t.esEmail) {
      b += `  → Borrador creado en Gmail: "${t.asunto}" (sin destinatario: pon el email, revisa y envía tú).`;
    } else {
      b += `  → Canal no-email: copiar/pegar a mano. Texto propuesto:\n\n${t.textoToque.split('\n').map((l) => '    ' + l).join('\n')}`;
    }
    return b;
  });
  cuerpo = `Toques de seguimiento 3-7-14 que tocan HOY (${hoy}): ${items.length}\n\n${bloques.join('\n\n')}\n\n— Nada se envía solo: revisa cada borrador, ajusta y envíalo tú.\n— Tras enviar, registra el toque en ventas/seguimiento.md (o pídeselo al agente de ventas).\n\nFuente: ventas/seguimiento.md · Workflow: Qualivo · Seguimientos 3-7-14`;
}

return [{ json: { asunto: `[Qualivo] Toques 3-7-14 de hoy — ${titulo}`, cuerpo } }];
